-- SEC-051/052 Evidence Vault — funções canônicas e catálogo sanitizado.
CREATE OR REPLACE FUNCTION resolve_evidence_scope(p_incident_id uuid,p_event_id uuid,p_recording_id uuid) RETURNS TABLE(organization_id uuid,neighborhood_id uuid,property_id uuid) LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path TO public AS $$ DECLARE v_org uuid;v_neigh uuid;v_prop uuid;t_org uuid;t_neigh uuid;t_prop uuid;BEGIN IF p_incident_id IS NULL AND p_event_id IS NULL AND p_recording_id IS NULL THEN RAISE EXCEPTION 'evidence_source_required';END IF;IF p_incident_id IS NOT NULL THEN SELECT i.organization_id,i.neighborhood_id,i.property_id INTO v_org,v_neigh,v_prop FROM incidents i WHERE i.id=p_incident_id;IF NOT FOUND THEN RAISE EXCEPTION 'incident_not_found';END IF;END IF;IF p_event_id IS NOT NULL THEN SELECT e.organization_id,e.neighborhood_id,e.property_id INTO t_org,t_neigh,t_prop FROM security_events e WHERE e.id=p_event_id;IF NOT FOUND THEN RAISE EXCEPTION 'event_not_found';END IF;IF v_org IS NULL THEN v_org:=t_org;v_neigh:=t_neigh;v_prop:=t_prop;ELSIF v_org<>t_org OR v_neigh IS DISTINCT FROM t_neigh OR v_prop IS DISTINCT FROM t_prop THEN RAISE EXCEPTION 'evidence_scope_mismatch';END IF;END IF;IF p_recording_id IS NOT NULL THEN SELECT r.organization_id,d.neighborhood_id,d.property_id INTO t_org,t_neigh,t_prop FROM recordings r JOIN devices d ON d.id=r.device_id WHERE r.id=p_recording_id;IF NOT FOUND THEN RAISE EXCEPTION 'recording_not_found';END IF;IF v_org IS NULL THEN v_org:=t_org;v_neigh:=t_neigh;v_prop:=t_prop;ELSIF v_org<>t_org OR v_neigh IS DISTINCT FROM t_neigh OR v_prop IS DISTINCT FROM t_prop THEN RAISE EXCEPTION 'evidence_scope_mismatch';END IF;END IF;RETURN QUERY SELECT v_org,v_neigh,v_prop;END $$;
CREATE OR REPLACE FUNCTION append_evidence_action(p_evidence_id uuid,p_action_type text,p_details jsonb DEFAULT '{}'::jsonb) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path TO public,auth AS $$ DECLARE v_org uuid;v_actor uuid;v_previous text;v_id uuid:=gen_random_uuid();v_created timestamptz:=clock_timestamp();v_hash text;BEGIN SELECT organization_id INTO v_org FROM evidence WHERE id=p_evidence_id;IF NOT FOUND THEN RAISE EXCEPTION 'evidence_not_found';END IF;v_actor:=app_current_user_id();SELECT action_hash INTO v_previous FROM evidence_actions WHERE evidence_id=p_evidence_id ORDER BY created_at DESC,id DESC LIMIT 1;v_hash:=encode(digest(concat_ws('|',v_id::text,p_evidence_id::text,v_org::text,COALESCE(v_actor::text,''),p_action_type,COALESCE(p_details,'{}'::jsonb)::text,COALESCE(v_previous,''),v_created::text),'sha256'),'hex');INSERT INTO evidence_actions(id,organization_id,evidence_id,actor_user_id,action_type,details,previous_action_hash,action_hash,created_at) VALUES(v_id,v_org,p_evidence_id,v_actor,p_action_type,COALESCE(p_details,'{}'::jsonb),v_previous,v_hash,v_created);RETURN v_id;END $$;
REVOKE ALL ON FUNCTION resolve_evidence_scope(uuid,uuid,uuid) FROM PUBLIC,authenticated,anonymous;REVOKE ALL ON FUNCTION append_evidence_action(uuid,text,jsonb) FROM PUBLIC,authenticated,anonymous;
CREATE OR REPLACE FUNCTION register_evidence_manifest(p_incident_id uuid,p_event_id uuid,p_recording_id uuid,p_evidence_type text,p_storage_key text,p_sha256 text,p_captured_at timestamptz,p_retained_until timestamptz,p_mime_type text,p_file_size_bytes bigint,p_original_filename text DEFAULT NULL,p_retention_reason text DEFAULT NULL,p_legal_hold boolean DEFAULT false) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path TO public,auth AS $$ DECLARE v_org uuid;v_neigh uuid;v_prop uuid;v_id uuid:=gen_random_uuid();v_actor uuid:=app_current_user_id();v_sha text:=lower(trim(p_sha256));v_manifest text;BEGIN SELECT organization_id,neighborhood_id,property_id INTO v_org,v_neigh,v_prop FROM resolve_evidence_scope(p_incident_id,p_event_id,p_recording_id);IF v_actor IS NULL THEN RAISE EXCEPTION 'authentication_required';END IF;IF NOT app_can_manage_evidence_scope(v_org,v_neigh,v_prop) THEN RAISE EXCEPTION 'evidence_management_required';END IF;IF p_evidence_type IS NULL OR btrim(p_evidence_type)='' THEN RAISE EXCEPTION 'evidence_type_required';END IF;IF p_storage_key IS NULL OR btrim(p_storage_key)='' OR position('://' in p_storage_key)>0 THEN RAISE EXCEPTION 'opaque_storage_key_required';END IF;IF v_sha !~ '^[0-9a-f]{64}$' THEN RAISE EXCEPTION 'invalid_sha256';END IF;IF p_captured_at IS NULL OR p_captured_at>now()+interval '5 minutes' THEN RAISE EXCEPTION 'invalid_captured_at';END IF;IF p_file_size_bytes IS NOT NULL AND p_file_size_bytes<=0 THEN RAISE EXCEPTION 'invalid_file_size';END IF;IF p_mime_type IS NULL OR btrim(p_mime_type)='' THEN RAISE EXCEPTION 'mime_type_required';END IF;IF COALESCE(btrim(p_retention_reason),'')='' THEN RAISE EXCEPTION 'retention_reason_required';END IF;IF NOT p_legal_hold AND (p_retained_until IS NULL OR p_retained_until<=now()) THEN RAISE EXCEPTION 'future_retention_required';END IF;v_manifest:=encode(digest(concat_ws('|',v_id::text,v_org::text,COALESCE(p_incident_id::text,''),COALESCE(p_event_id::text,''),COALESCE(p_recording_id::text,''),p_evidence_type,p_storage_key,v_sha,p_captured_at::text,COALESCE(p_retained_until::text,''),p_mime_type,COALESCE(p_file_size_bytes::text,''),p_legal_hold::text),'sha256'),'hex');INSERT INTO evidence(id,organization_id,incident_id,event_id,recording_id,evidence_type,storage_key,sha256,captured_at,retained_until,mime_type,file_size_bytes,original_filename,integrity_status,retention_reason,legal_hold,manifest_hash,registered_by) VALUES(v_id,v_org,p_incident_id,p_event_id,p_recording_id,btrim(p_evidence_type),btrim(p_storage_key),v_sha,p_captured_at,p_retained_until,btrim(p_mime_type),p_file_size_bytes,NULLIF(btrim(p_original_filename),''),'unverified',btrim(p_retention_reason),p_legal_hold,v_manifest,v_actor);PERFORM append_evidence_action(v_id,'registered',jsonb_build_object('sha256',v_sha,'manifestHash',v_manifest,'type',p_evidence_type,'retainedUntil',p_retained_until,'legalHold',p_legal_hold));IF p_legal_hold THEN PERFORM append_evidence_action(v_id,'legal_hold_enabled',jsonb_build_object('reason',p_retention_reason));END IF;RETURN v_id;END $$;
GRANT EXECUTE ON FUNCTION register_evidence_manifest(uuid,uuid,uuid,text,text,text,timestamptz,timestamptz,text,bigint,text,text,boolean) TO authenticated;
CREATE OR REPLACE FUNCTION verify_evidence_hash(p_evidence_id uuid,p_observed_sha256 text) RETURNS text LANGUAGE plpgsql SECURITY DEFINER SET search_path TO public,auth AS $$ DECLARE v_org uuid;v_neigh uuid;v_prop uuid;v_expected text;v_observed text:=lower(trim(p_observed_sha256));v_status text;BEGIN SELECT e.sha256,s.organization_id,s.neighborhood_id,s.property_id INTO v_expected,v_org,v_neigh,v_prop FROM evidence e CROSS JOIN LATERAL resolve_evidence_scope(e.incident_id,e.event_id,e.recording_id) s WHERE e.id=p_evidence_id;IF NOT FOUND THEN RAISE EXCEPTION 'evidence_not_found';END IF;IF NOT app_can_manage_evidence_scope(v_org,v_neigh,v_prop) THEN RAISE EXCEPTION 'evidence_management_required';END IF;IF v_observed !~ '^[0-9a-f]{64}$' THEN RAISE EXCEPTION 'invalid_sha256';END IF;v_status:=CASE WHEN v_observed=v_expected THEN 'verified' ELSE 'mismatch' END;UPDATE evidence SET integrity_status=v_status,verified_at=now(),verified_by=app_current_user_id(),sealed_at=CASE WHEN v_status='verified' THEN now() ELSE sealed_at END WHERE id=p_evidence_id;PERFORM append_evidence_action(p_evidence_id,'integrity_'||v_status,jsonb_build_object('observedSha256',v_observed,'expectedSha256',v_expected));RETURN v_status;END $$;GRANT EXECUTE ON FUNCTION verify_evidence_hash(uuid,text) TO authenticated;
CREATE OR REPLACE FUNCTION extend_evidence_retention(p_evidence_id uuid,p_retained_until timestamptz,p_reason text) RETURNS timestamptz LANGUAGE plpgsql SECURITY DEFINER SET search_path TO public,auth AS $$ DECLARE v_org uuid;v_neigh uuid;v_prop uuid;v_current timestamptz;BEGIN SELECT e.retained_until,s.organization_id,s.neighborhood_id,s.property_id INTO v_current,v_org,v_neigh,v_prop FROM evidence e CROSS JOIN LATERAL resolve_evidence_scope(e.incident_id,e.event_id,e.recording_id) s WHERE e.id=p_evidence_id;IF NOT FOUND THEN RAISE EXCEPTION 'evidence_not_found';END IF;IF NOT app_can_manage_evidence_scope(v_org,v_neigh,v_prop) THEN RAISE EXCEPTION 'evidence_management_required';END IF;IF p_retained_until IS NULL OR p_retained_until<=now() OR (v_current IS NOT NULL AND p_retained_until<=v_current) THEN RAISE EXCEPTION 'retention_must_extend';END IF;IF COALESCE(btrim(p_reason),'')='' THEN RAISE EXCEPTION 'retention_reason_required';END IF;UPDATE evidence SET retained_until=p_retained_until,retention_reason=btrim(p_reason) WHERE id=p_evidence_id;PERFORM append_evidence_action(p_evidence_id,'retention_extended',jsonb_build_object('from',v_current,'to',p_retained_until,'reason',btrim(p_reason)));RETURN p_retained_until;END $$;GRANT EXECUTE ON FUNCTION extend_evidence_retention(uuid,timestamptz,text) TO authenticated;
CREATE OR REPLACE FUNCTION set_evidence_legal_hold(p_evidence_id uuid,p_enabled boolean,p_reason text) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path TO public,auth AS $$ DECLARE v_org uuid;v_current boolean;BEGIN SELECT e.organization_id,e.legal_hold INTO v_org,v_current FROM evidence e WHERE e.id=p_evidence_id;IF NOT FOUND THEN RAISE EXCEPTION 'evidence_not_found';END IF;IF NOT(app_is_platform_admin() OR app_has_org_role(v_org,ARRAY['admin_organization'])) THEN RAISE EXCEPTION 'organization_admin_required';END IF;IF COALESCE(btrim(p_reason),'')='' THEN RAISE EXCEPTION 'legal_hold_reason_required';END IF;IF v_current=p_enabled THEN RETURN v_current;END IF;IF NOT p_enabled AND (SELECT retained_until FROM evidence WHERE id=p_evidence_id) IS NULL THEN RAISE EXCEPTION 'retention_required_before_release';END IF;UPDATE evidence SET legal_hold=p_enabled,retention_reason=btrim(p_reason) WHERE id=p_evidence_id;PERFORM append_evidence_action(p_evidence_id,CASE WHEN p_enabled THEN 'legal_hold_enabled' ELSE 'legal_hold_released' END,jsonb_build_object('reason',btrim(p_reason)));RETURN p_enabled;END $$;GRANT EXECUTE ON FUNCTION set_evidence_legal_hold(uuid,boolean,text) TO authenticated;
CREATE OR REPLACE FUNCTION request_evidence_export(p_evidence_id uuid,p_request_type text,p_purpose text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path TO public,auth AS $$ DECLARE v_id uuid:=gen_random_uuid();v_org uuid;v_neigh uuid;v_prop uuid;v_user uuid:=app_current_user_id();v_integrity text;BEGIN SELECT e.organization_id,e.integrity_status,s.neighborhood_id,s.property_id INTO v_org,v_integrity,v_neigh,v_prop FROM evidence e CROSS JOIN LATERAL resolve_evidence_scope(e.incident_id,e.event_id,e.recording_id) s WHERE e.id=p_evidence_id;IF NOT FOUND THEN RAISE EXCEPTION 'evidence_not_found';END IF;IF v_user IS NULL OR NOT app_has_scope_access(v_org,v_neigh,v_prop) THEN RAISE EXCEPTION 'evidence_access_required';END IF;IF p_request_type NOT IN('download','share') THEN RAISE EXCEPTION 'invalid_export_type';END IF;IF COALESCE(btrim(p_purpose),'')='' THEN RAISE EXCEPTION 'purpose_required';END IF;IF v_integrity='mismatch' THEN RAISE EXCEPTION 'integrity_mismatch_blocks_export';END IF;INSERT INTO evidence_export_requests(id,organization_id,evidence_id,requester_user_id,request_type,purpose,status) VALUES(v_id,v_org,p_evidence_id,v_user,p_request_type,btrim(p_purpose),'blocked_storage');PERFORM append_evidence_action(p_evidence_id,p_request_type||'_requested',jsonb_build_object('requestId',v_id,'purpose',btrim(p_purpose),'status','blocked_storage'));RETURN v_id;END $$;GRANT EXECUTE ON FUNCTION request_evidence_export(uuid,text,text) TO authenticated;
CREATE OR REPLACE FUNCTION get_evidence_vault() RETURNS TABLE(id uuid,evidence_type text,sha256 text,manifest_hash text,mime_type text,file_size_bytes bigint,integrity_status text,captured_at timestamptz,retained_until timestamptz,legal_hold boolean,retention_reason text,incident_id uuid,event_id uuid,recording_id uuid,registered_at timestamptz,verified_at timestamptz,action_count bigint) LANGUAGE sql STABLE SECURITY DEFINER SET search_path TO public,auth AS $$ SELECT e.id,e.evidence_type,e.sha256,e.manifest_hash,e.mime_type,e.file_size_bytes,e.integrity_status,e.captured_at,e.retained_until,e.legal_hold,e.retention_reason,e.incident_id,e.event_id,e.recording_id,e.created_at,e.verified_at,(SELECT count(*) FROM evidence_actions a WHERE a.evidence_id=e.id) FROM evidence e WHERE(e.incident_id IS NOT NULL OR e.event_id IS NOT NULL OR e.recording_id IS NOT NULL) AND(e.incident_id IS NULL OR EXISTS(SELECT 1 FROM incidents i WHERE i.id=e.incident_id AND app_has_scope_access(i.organization_id,i.neighborhood_id,i.property_id))) AND(e.event_id IS NULL OR EXISTS(SELECT 1 FROM security_events se WHERE se.id=e.event_id AND app_has_scope_access(se.organization_id,se.neighborhood_id,se.property_id))) AND(e.recording_id IS NULL OR EXISTS(SELECT 1 FROM recordings r JOIN devices d ON d.id=r.device_id WHERE r.id=e.recording_id AND app_has_scope_access(r.organization_id,d.neighborhood_id,d.property_id))) ORDER BY e.created_at DESC $$;GRANT EXECUTE ON FUNCTION get_evidence_vault() TO authenticated;
CREATE OR REPLACE FUNCTION get_evidence_timeline(p_evidence_id uuid) RETURNS TABLE(id uuid,action_type text,actor_user_id uuid,details jsonb,previous_action_hash text,action_hash text,created_at timestamptz) LANGUAGE sql STABLE SECURITY DEFINER SET search_path TO public,auth AS $$ SELECT a.id,a.action_type,a.actor_user_id,a.details,a.previous_action_hash,a.action_hash,a.created_at FROM evidence_actions a JOIN evidence e ON e.id=a.evidence_id WHERE a.evidence_id=p_evidence_id AND((e.incident_id IS NOT NULL AND EXISTS(SELECT 1 FROM incidents i WHERE i.id=e.incident_id AND app_has_scope_access(i.organization_id,i.neighborhood_id,i.property_id))) OR(e.event_id IS NOT NULL AND EXISTS(SELECT 1 FROM security_events se WHERE se.id=e.event_id AND app_has_scope_access(se.organization_id,se.neighborhood_id,se.property_id))) OR(e.recording_id IS NOT NULL AND EXISTS(SELECT 1 FROM recordings r JOIN devices d ON d.id=r.device_id WHERE r.id=e.recording_id AND app_has_scope_access(r.organization_id,d.neighborhood_id,d.property_id)))) ORDER BY a.created_at,a.id $$;GRANT EXECUTE ON FUNCTION get_evidence_timeline(uuid) TO authenticated;
CREATE OR REPLACE FUNCTION register_recording_manifest(p_device_id uuid,p_storage_key text,p_sha256 text,p_starts_at timestamptz,p_ends_at timestamptz,p_retained_until timestamptz,p_mime_type text,p_file_size_bytes bigint) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path TO public,auth AS $$ DECLARE v_id uuid:=gen_random_uuid();v_org uuid;v_neigh uuid;v_prop uuid;v_sha text:=lower(trim(p_sha256));BEGIN SELECT organization_id,neighborhood_id,property_id INTO v_org,v_neigh,v_prop FROM devices WHERE id=p_device_id;IF NOT FOUND THEN RAISE EXCEPTION 'device_not_found';END IF;IF v_prop IS NOT NULL THEN IF NOT app_can_manage_property(v_prop) THEN RAISE EXCEPTION 'property_management_required';END IF;ELSIF v_neigh IS NOT NULL THEN IF NOT app_can_manage_neighborhood(v_neigh) THEN RAISE EXCEPTION 'neighborhood_management_required';END IF;ELSE RAISE EXCEPTION 'device_scope_required';END IF;IF p_storage_key IS NULL OR btrim(p_storage_key)='' OR position('://' in p_storage_key)>0 THEN RAISE EXCEPTION 'opaque_storage_key_required';END IF;IF v_sha !~ '^[0-9a-f]{64}$' THEN RAISE EXCEPTION 'invalid_sha256';END IF;IF p_starts_at IS NULL OR p_ends_at IS NULL OR p_ends_at<=p_starts_at THEN RAISE EXCEPTION 'invalid_recording_window';END IF;IF p_retained_until IS NULL OR p_retained_until<=now() THEN RAISE EXCEPTION 'future_retention_required';END IF;IF COALESCE(btrim(p_mime_type),'')='' THEN RAISE EXCEPTION 'mime_type_required';END IF;IF p_file_size_bytes IS NOT NULL AND p_file_size_bytes<=0 THEN RAISE EXCEPTION 'invalid_file_size';END IF;INSERT INTO recordings(id,organization_id,device_id,storage_key,starts_at,ends_at,retained_until,sha256,mime_type,file_size_bytes,integrity_status) VALUES(v_id,v_org,p_device_id,btrim(p_storage_key),p_starts_at,p_ends_at,p_retained_until,v_sha,btrim(p_mime_type),p_file_size_bytes,'unverified');INSERT INTO audit_logs(organization_id,actor_user_id,action,entity_type,entity_id,details) VALUES(v_org,app_current_user_id(),'recording.registered','recording',v_id,jsonb_build_object('deviceId',p_device_id,'sha256',v_sha,'startsAt',p_starts_at,'endsAt',p_ends_at,'retainedUntil',p_retained_until));RETURN v_id;END $$;GRANT EXECUTE ON FUNCTION register_recording_manifest(uuid,text,text,timestamptz,timestamptz,timestamptz,text,bigint) TO authenticated;
CREATE OR REPLACE FUNCTION verify_recording_hash(p_recording_id uuid,p_observed_sha256 text) RETURNS text LANGUAGE plpgsql SECURITY DEFINER SET search_path TO public,auth AS $$ DECLARE v_expected text;v_org uuid;v_neigh uuid;v_prop uuid;v_status text;v_observed text:=lower(trim(p_observed_sha256));BEGIN SELECT r.sha256,r.organization_id,d.neighborhood_id,d.property_id INTO v_expected,v_org,v_neigh,v_prop FROM recordings r JOIN devices d ON d.id=r.device_id WHERE r.id=p_recording_id;IF NOT FOUND THEN RAISE EXCEPTION 'recording_not_found';END IF;IF v_prop IS NOT NULL THEN IF NOT app_can_manage_property(v_prop) THEN RAISE EXCEPTION 'property_management_required';END IF;ELSIF v_neigh IS NOT NULL THEN IF NOT app_can_manage_neighborhood(v_neigh) THEN RAISE EXCEPTION 'neighborhood_management_required';END IF;END IF;IF v_observed !~ '^[0-9a-f]{64}$' THEN RAISE EXCEPTION 'invalid_sha256';END IF;v_status:=CASE WHEN v_observed=v_expected THEN 'verified' ELSE 'mismatch' END;UPDATE recordings SET integrity_status=v_status,verified_at=now(),verified_by=app_current_user_id() WHERE id=p_recording_id;INSERT INTO audit_logs(organization_id,actor_user_id,action,entity_type,entity_id,details) VALUES(v_org,app_current_user_id(),'recording.integrity_'||v_status,'recording',p_recording_id,jsonb_build_object('observedSha256',v_observed,'expectedSha256',v_expected));RETURN v_status;END $$;GRANT EXECUTE ON FUNCTION verify_recording_hash(uuid,text) TO authenticated;
CREATE OR REPLACE FUNCTION get_recordings_catalog() RETURNS TABLE(id uuid,device_id uuid,device_name text,device_type device_type,community_shared boolean,starts_at timestamptz,ends_at timestamptz,retained_until timestamptz,sha256 text,mime_type text,file_size_bytes bigint,integrity_status text,verified_at timestamptz) LANGUAGE sql STABLE SECURITY DEFINER SET search_path TO public,auth AS $$ SELECT r.id,r.device_id,d.name,d.device_type,d.community_shared,r.starts_at,r.ends_at,r.retained_until,r.sha256,r.mime_type,r.file_size_bytes,r.integrity_status,r.verified_at FROM recordings r JOIN devices d ON d.id=r.device_id WHERE app_has_scope_access(r.organization_id,d.neighborhood_id,d.property_id) ORDER BY r.starts_at DESC $$;GRANT EXECUTE ON FUNCTION get_recordings_catalog() TO authenticated;
ALTER POLICY evidence_export_requests_scope_read ON evidence_export_requests USING(requester_user_id=app_current_user_id() OR EXISTS(SELECT 1 FROM evidence e WHERE e.id=evidence_export_requests.evidence_id AND app_can_manage_evidence_scope(e.organization_id,COALESCE((SELECT i.neighborhood_id FROM incidents i WHERE i.id=e.incident_id),(SELECT se.neighborhood_id FROM security_events se WHERE se.id=e.event_id),(SELECT d.neighborhood_id FROM recordings r JOIN devices d ON d.id=r.device_id WHERE r.id=e.recording_id)),COALESCE((SELECT i.property_id FROM incidents i WHERE i.id=e.incident_id),(SELECT se.property_id FROM security_events se WHERE se.id=e.event_id),(SELECT d.property_id FROM recordings r JOIN devices d ON d.id=r.device_id WHERE r.id=e.recording_id)))));
